    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101116"><meta name="robots" content="noindex,nofollow"><title><?=$page==='accounts'?'Accounts':'Account settings'?> · AZHottie</title><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/production.css"><link rel="stylesheet" href="assets/accounts.css"><link rel="stylesheet" href="assets/universal-header.css?v=1.18.1"><link rel="stylesheet" href="assets/member-layout.css"><link rel="stylesheet" href="assets/social.css"></head><body data-page="<?=az_h($page==='settings'?'account':$page)?>"><?php az_render_universal_header($page, $user); ?><?php az_render_member_layout_open($page, $user); ?><?php az_render_account_view($page);?><?php az_render_member_layout_close(); ?><footer class="studio-footer"><span>AZHOTTIE · YOUR COMMUNITY</span><span>One account. Your roles.</span></footer><script type="module" src="assets/accounts.js"></script><?php if($page==='settings'):?><script type="module" src="assets/social-settings.js"></script><?php endif;?></body></html><?php
}

